/**
 * The campaigns this endpoint serves. A campaign supplies its own form definition, its own
 * routing and its own copy; everything else (storage, the register lookup, delivery,
 * alerts, tracking) is shared. Adding a campaign is one folder under g/, one import here and
 * one entry in each Zap's CAMPAIGNS.
 *
 * The page data (config, form copy, the landing page split around the form) is generated by
 * scripts/build-g-growth.mjs into data.generated.mjs, one entry per funnel.
 */
import * as itCore from '../../../g/uk-it-growth/core.mjs';
import * as itRoute from '../../../g/uk-it-growth/route.mjs';
import { renderForm as itRenderForm } from '../../../g/uk-it-growth/render-form.mjs';
import * as healthCore from '../../../g/uk-private-hospitals/core.mjs';
import * as healthRoute from '../../../g/uk-private-hospitals/route.mjs';
import { renderForm as healthRenderForm } from '../../../g/uk-private-hospitals/render-form.mjs';
import * as lawCore from '../../../g/uk-law-firms/core.mjs';
import * as lawRoute from '../../../g/uk-law-firms/route.mjs';
import { renderForm as lawRenderForm } from '../../../g/uk-law-firms/render-form.mjs';
import * as itaCore from '../../../g/it-ict-growth/core.mjs';
import * as itaRoute from '../../../g/it-ict-growth/route.mjs';
import { renderForm as itaRenderForm } from '../../../g/it-ict-growth/render-form.mjs';
import { funnels } from './data.generated.mjs';

const CODE = {
  'uk-it-growth': { core: itCore, route: itRoute, renderForm: itRenderForm },
  'uk-private-hospitals': { core: healthCore, route: healthRoute, renderForm: healthRenderForm },
  'uk-law-firms': { core: lawCore, route: lawRoute, renderForm: lawRenderForm },
  'it-ict-growth': { core: itaCore, route: itaRoute, renderForm: itaRenderForm },
};

export const campaigns = {};
for (const [slug, data] of Object.entries(funnels)) {
  const code = CODE[slug];
  if (!code) throw new Error(`data.generated.mjs has a funnel "${slug}" that campaigns.mjs does not know`);
  campaigns[data.cfg.campaign] = {
    id: data.cfg.campaign,
    cfg: data.cfg,
    copy: data.copy,
    shell: data.shell,
    core: code.core,
    route: code.route,
    renderForm: code.renderForm,
    /** The name looked up in Companies House. */
    registryName: (values) => values.company_name,
    /** Routes that count as a qualified form for Meta (Conversions API and pixel). */
    qualifiedRoutes: ['fit', 'review'],
  };
}
